(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let csrf='',data={products:[],bookings:[],categories:[]},editing=null,booking=null,view='menu';
const status=(selector,message,error=false)=>{const el=$(selector);el.textContent=message;el.dataset.error=String(error)};
async function api(action,method='GET',body){const r=await fetch('/api/app?action='+action,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(method!=='GET'&&csrf?{'X-CSRF-Token':csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});const result=await r.json();if(!r.ok){if(r.status===401&&action!=='login')showLogin();throw Error(result.error||'No se pudo completar la operación.')}return result}
function showLogin(){csrf='';data={products:[],bookings:[],categories:[]};$('#products').replaceChildren();$('#bookings').replaceChildren();$$('dialog[open]').forEach(d=>d.close());$('#workspace').hidden=true;$('#login-view').hidden=false;$('#logout').hidden=true}
function showWorkspace(){$('#workspace').hidden=false;$('#login-view').hidden=true;$('#logout').hidden=false}
function node(tag,content,cls){const e=document.createElement(tag);if(content!==undefined)e.textContent=content;if(cls)e.className=cls;return e}
function options(select,rows){select.replaceChildren(...rows.map(([value,label])=>{const o=node('option',label);o.value=value;return o}))}
const money=p=>p.price===null?'Consultar':new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(p.price)+(p.unit==='100g'?' / 100 g':'');
const states={pending:'Pendiente',confirmed:'Confirmada',cancelled:'Cancelada'};
async function load(){data=await api('admin-data');const previous=$('#product-category').value;options($('#product-category'),[['all','Todas'],...data.categories.map(c=>[c.id,c.es])]);$('#product-category').value=previous||'all';options($('#product-form').elements.category,data.categories.map(c=>[c.id,c.es]));$('#pending-count').textContent=String(data.bookings.filter(b=>b.status==='pending').length);renderProducts();renderBookings()}
function renderProducts(){const q=$('#product-search').value.toLowerCase(),category=$('#product-category').value;const list=$('#products');list.replaceChildren();const products=data.products.filter(p=>(category==='all'||p.category===category)&&p.name.toLowerCase().includes(q));for(const p of products){const row=node('article',undefined,'product-row'),img=node('img');img.src=p.image;img.alt=p.name;img.loading='lazy';const copy=node('div');copy.append(node('h3',p.name),node('p',(data.categories.find(c=>c.id===p.category)?.es||'')+(p.active?'':' · Oculto'),'product-meta'));const edit=node('button','Editar','quiet');edit.addEventListener('click',()=>openProduct(p));row.append(img,copy,node('p',money(p),'product-price'),edit);list.append(row)}if(!products.length)list.append(node('p','No hay platos con estos filtros.','empty'))}
function renderBookings(){const list=$('#bookings'),state=$('#booking-status-filter').value,date=$('#booking-date-filter').value,q=$('#booking-search').value.toLowerCase();list.replaceChildren();const bookings=data.bookings.filter(b=>(state==='all'||b.status===state)&&(!date||date===b.date)&&(b.name+' '+b.email).toLowerCase().includes(q));for(const b of bookings){const card=node('article',undefined,'booking-card'),copy=node('div'),email=node('a',b.email);email.href='mailto:'+b.email;copy.append(node('span',states[b.status],'badge '+b.status),node('h3',b.name),node('p',b.date.split('-').reverse().join('/')+' · '+b.guests+' personas · '+(b.service==='comida'?'Comida':'Cena')),email);const edit=node('button','Gestionar','quiet');edit.addEventListener('click',()=>openBooking(b));card.append(copy,edit);list.append(card)}if(!bookings.length)list.append(node('p','No hay reservas con estos filtros.','empty'))}
function openProduct(p){editing=p?{...p}:{id:null,name:'',nameEn:'',category:data.categories[0]?.id||'picar',price:null,unit:'portion',active:true,description:'',descriptionEn:'',image:'assets/images/logo.webp'};const f=$('#product-form');f.reset();for(const key of ['name','nameEn','category','unit','description','descriptionEn'])f.elements[key].value=editing[key]||'';f.elements.price.value=editing.price===null?'':editing.price;f.elements.active.value=String(editing.active);$('#product-preview').src=editing.image;$('#product-title').textContent=p?'Editar plato':'Añadir plato';status('#product-status','');$('#product-dialog').showModal()}
function openBooking(b){booking={...b};$('#booking-customer').textContent=b.name+' · '+b.email;const f=$('#booking-editor');for(const key of ['date','guests','service','status'])f.elements[key].value=b[key];status('#booking-editor-status','');$('#booking-dialog').showModal()}
async function upload(file){if(file.size>15*1024*1024)throw Error('La imagen original debe pesar menos de 15 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Selecciona JPG, PNG o WebP.');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const image=canvas.toDataURL('image/webp',.86);const result=await api('upload','POST',{type:'image/webp',data:image.split(',')[1]});return result.image}
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter||event.currentTarget.querySelector('[type="submit"]');button.disabled=true;status('#login-status','Entrando…');try{const result=await api('login','POST',{pin:$('#pin').value});csrf=result.csrf;$('#pin').value='';await load();showWorkspace();status('#login-status','')}catch(e){status('#login-status',e.message,true)}finally{button.disabled=false}});
$('#logout').addEventListener('click',async()=>{try{await api('logout','POST',{});showLogin()}catch(e){status('#workspace-status',e.message,true)}});
$('#refresh').addEventListener('click',async()=>{try{await load();status('#workspace-status','Datos actualizados.')}catch(e){status('#workspace-status',e.message,true)}});
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;$$('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('#menu-view').hidden=view!=='menu';$('#reservations-view').hidden=view!=='reservations';$('#workspace-title').textContent=view==='menu'?'La carta.':'Las reservas.';status('#workspace-status','')}));
for(const id of ['product-search','product-category'])$('#'+id).addEventListener('input',renderProducts);for(const id of ['booking-status-filter','booking-date-filter','booking-search'])$('#'+id).addEventListener('input',renderBookings);
$('#new-product').addEventListener('click',()=>openProduct(null));$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#product-photo').addEventListener('change',()=>{const file=$('#product-photo').files[0];if(file){const url=URL.createObjectURL(file);$('#product-preview').src=url;$('#product-preview').onload=()=>URL.revokeObjectURL(url)}});
$('#product-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter||event.currentTarget.querySelector('[type="submit"]');button.disabled=true;status('#product-status','Guardando…');try{const f=event.currentTarget;const image=$('#product-photo').files[0]?await upload($('#product-photo').files[0]):editing.image;const values=Object.fromEntries(new FormData(f));const product={...values,id:editing.id,version:editing.version,price:values.price===''?null:Number(values.price),active:values.active==='true',image};await api('product',editing.id?'PUT':'POST',product);$('#product-dialog').close();await load();status('#workspace-status','Plato guardado. El cambio ya está publicado.')}catch(e){status('#product-status',e.message,true)}finally{button.disabled=false}});
$('#booking-editor').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter||event.currentTarget.querySelector('[type="submit"]');button.disabled=true;status('#booking-editor-status','Guardando…');try{const values=Object.fromEntries(new FormData(event.currentTarget));await api('reservation','PUT',{...values,guests:Number(values.guests),id:booking.id,version:booking.version});$('#booking-dialog').close();await load();status('#workspace-status','Reserva actualizada. Recuerda avisar al cliente.')}catch(e){status('#booking-editor-status',e.message,true)}finally{button.disabled=false}});
(async()=>{try{const result=await api('session');csrf=result.csrf;await load();showWorkspace()}catch(e){showLogin();if(!e.message.includes('Inicia sesión'))status('#login-status',e.message,true)}})();
})();
